  3	public final class ArrayDisjointSet implements DisjointSet {
  4	    private static final String NEGATIVE_SIZE_MESSAGE = "size must be non-negative";
  5	
  6	    private final int[] parent;
  7	    private final int[] rank;
  8	    private final int[] componentSize;
  9	    private int componentCount;
 10	
 11	    public ArrayDisjointSet(int size) {
 12	        validateSize(size);
 13	        parent = new int[size];
 14	        rank = new int[size];
 15	        componentSize = new int[size];
 16	        componentCount = size;
 17	        initializeSingletonSets();
 18	    }
 19	
 20	    @Override
 21	    public int find(int element) {
 22	        validateIndex(element);
 23	        return findRoot(element);
 24	    }
 25	
 26	    @Override
 27	    public boolean union(int first, int second) {
 28	        int firstRoot = find(first);
 29	        int secondRoot = find(second);
 30	        if (firstRoot == secondRoot) {
 31	            return false;
 32	        }
 33	
 34	        mergeDistinctRoots(firstRoot, secondRoot);
 35	        componentCount--;
 36	        return true;
 37	    }
 38	
 39	    @Override
 40	    public boolean connected(int first, int second) {
 41	        return find(first) == find(second);
 42	    }
 43	
 44	    @Override
 45	    public int componentSize(int element) {
 46	        return componentSize[find(element)];
 47	    }
 48	
 49	    @Override
 50	    public int components() {
 51	        return componentCount;
 52	    }
 53	
 54	    @Override
 55	    public int size() {
 56	        return parent.length;
 57	    }
 58	
 59	    private void initializeSingletonSets() {
 60	        for (int i = 0; i < parent.length; i++) {
 61	            parent[i] = i;
 62	            componentSize[i] = 1;
 63	        }
 64	    }
 65	
 66	    private int findRoot(int element) {
 67	        int current = element;
 68	        int root = current;
 69	        while (parent[root] != root) {
 70	            root = parent[root];
 71	        }
 72	
 73	        while (current != root) {
 74	            int next = parent[current];
 75	            parent[current] = root;
 76	            current = next;
 77	        }
 78	
 79	        return root;
 80	    }
 81	
 82	    private void mergeDistinctRoots(int firstRoot, int secondRoot) {
 83	        if (rank[firstRoot] < rank[secondRoot]) {
 84	            attachRoot(firstRoot, secondRoot);
 85	            return;
 86	        }
 87	
 88	        if (rank[firstRoot] > rank[secondRoot]) {
 89	            attachRoot(secondRoot, firstRoot);
 90	            return;
 91	        }
 92	
 93	        attachRoot(secondRoot, firstRoot);
 94	        rank[firstRoot]++;
 95	    }
 96	
 97	    private void attachRoot(int childRoot, int parentRoot) {
 98	        parent[childRoot] = parentRoot;
 99	        componentSize[parentRoot] += componentSize[childRoot];
100	    }
101	
102	    private static void validateSize(int size) {
103	        if (size < 0) {
104	            throw new IllegalArgumentException(NEGATIVE_SIZE_MESSAGE);
105	        }
106	    }
107	
108	    private void validateIndex(int element) {
109	        if (element < 0 || element >= parent.length) {
110	            throw new IndexOutOfBoundsException(outOfBoundsMessage(element));
111	        }
112	    }
113	
114	    private String outOfBoundsMessage(int element) {
115	        return "index " + element + " is out of bounds for size " + parent.length;
116	    }
117	}

